'use strict';
const $=s=>document.querySelector(s), app=$('#app'),dialog=$('#dialog');
const symbols={R:'→',L:'←',U:'↑',D:'↓',C:'⭐'},names={R:'Kanan',L:'Kiri',U:'Atas',D:'Bawah',C:'Jika ⭐, ambil'};
let done=[],storageOK=true;try{const s=JSON.parse(localStorage.getItem('kode-kecil-v1')||'[]');if(Array.isArray(s))done=[...new Set(s.filter(n=>Number.isInteger(n)&&n>=0&&n<40))];}catch{storageOK=false;}
let lesson=null,program=[],jurus=[],pos=[0,4],collected=new Set(),running=false,runId=0,sound=false;
const eq=(a,b)=>a[0]===b[0]&&a[1]===b[1],key=p=>p.join(',');
function say(text){if(sound&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='id-ID';u.rate=.85;speechSynthesis.speak(u);}}
function status(text){const el=$('#status');if(el)el.textContent=text;say(text);}
function stop(){runId++;running=false;}
function nextId(){return lessons.findIndex(l=>!done.includes(l.id));}
function map(){stop();lesson=null;const next=nextId();app.innerHTML=`<section class="hero"><div><div class="eyebrow">UNTUK PEMIKIR KECIL USIA 6 TAHUN</div><h1>Ide kecil.<br><em>Petualangan besar.</em></h1><p>Temani Bimo menjelajah dunia kode. Susun langkah, temukan pola, dan rayakan setiap “aku bisa!”</p><button class="primary" id="continue">${done.length?'Lanjut petualangan':'Mulai petualangan'} &nbsp; →</button><span class="hero-note">40 misi · main sesuai ritmemu</span></div><div class="scene" role="img" aria-label="Bimo, robot kuning, menjelajah taman menuju bendera"><span class="sun">☀️</span><span class="tree">🌳</span><span class="tree right">🌲</span><span class="trail">▪ ▪ ▪</span><div class="robot"></div><span class="flag">🚩</span><div class="bubble">Hai! Aku Bimo. Ayo main! ✨</div></div></section><section class="stats"><div><strong>🌟 ${done.length} / 40</strong><small>Misi selesai</small></div><div class="progress" role="progressbar" aria-label="Misi selesai" aria-valuenow="${done.length}" aria-valuemin="0" aria-valuemax="40"><i style="width:${done.length/40*100}%"></i></div><div><strong>8 pulau</strong><small>Penuh penemuan baru</small></div><span class="pill">🌱 Pelan-pelan, jadi bisa</span></section><div class="section-head"><div><h2>Peta petualanganmu</h2><p>Mulai dari taman. Satu misi, satu penemuan.</p></div><span class="pill">✦ 5 pertemuan tiap pulau</span></div><section class="worlds">${worlds.map((w,i)=>`<article class="world-card"><div class="world-art" style="--tint:${w.color}"><span class="number">PULAU 0${i+1}</span><span class="island">${w.icon}</span></div><div class="world-body"><h3>${w.name}</h3><p>${w.skill}</p><div class="lesson-dots">${lessons.slice(i*5,i*5+5).map(l=>`<button class="dot ${done.includes(l.id)?'done':l.id===next?'current':''}" data-lesson="${l.id}" aria-label="Pertemuan ${l.id+1}: ${l.title}${done.includes(l.id)?', selesai':''}" title="${l.title}">${done.includes(l.id)?'✓':l.id+1}</button>`).join('')}</div></div></article>`).join('')}</section><p class="footer-note">Tanpa skor cepat-cepatan. Tanpa takut salah. Banyak kesempatan mencoba. ♡<br>${storageOK?'Progres tersimpan di browser ini.':'Penyimpanan browser tidak tersedia; progres hanya untuk sesi ini.'}</p>`;$('#continue').onclick=()=>openLesson(next<0?0:next);app.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(+b.dataset.lesson));}
function instruction(){return lesson.world===2?'Ada panah yang keliru. Coba, hapus kartu yang salah, lalu susun lagi.':lesson.require==='repeat'?'Susun pola pendek, lalu bungkus dengan tombol Ulang. Bawa Bimo ke bendera!':lesson.require==='function'?'Susun langkah, simpan jadi Jurus, lalu panggil jurusmu. Ambil semua bintang!':lesson.stars.length?'Bawa Bimo ke bendera. Setelah tiba di bintang, pakai “Jika ⭐, ambil”.':'Susun panah agar Bimo sampai ke bendera merah. Ikuti jalan krem!';}
function openLesson(id){stop();lesson=lessons[id];program=structuredClone(lesson.starter);jurus=[];pos=[...lesson.start];collected=new Set();const w=worlds[lesson.world];app.innerHTML=`<button class="back" id="back">← Kembali ke peta</button><div class="play-top"><div><div class="eyebrow">${w.icon} ${w.name} · PERTEMUAN ${id+1} / 40</div><h1>${lesson.title}</h1></div><span class="pill">${w.skill}</span></div><div class="game-layout"><section class="board-wrap"><div class="board" id="board" role="img" aria-label="Papan petualangan Bimo"></div><p class="board-legend">🤖 Bimo &nbsp; · &nbsp; 🚩 Tujuan &nbsp; · &nbsp; 🌿 Di luar jalan</p><div class="status" id="status" role="status" aria-live="polite">${instruction()}</div><button class="secondary" id="listen" style="margin-top:12px">🔊 Bacakan petunjuk</button></section><section class="code-panel"><h2>Rencana langkahmu</h2><p>Ketuk panah untuk menambahkan. Ketuk kartu untuk menghapusnya.</p><div class="palette">${['L','U','D','R'].map(d=>`<button class="command" data-add="${d}" aria-label="Tambah ${names[d]}"><b>${symbols[d]}</b><small>${names[d]}</small></button>`).join('')}${lesson.world>=5?'<button class="command" data-add="C"><b>⭐ ?</b><small>Jika ⭐, ambil</small></button>':''}</div><div id="program" class="program" aria-label="Urutan instruksi"></div><div class="toolbar"><button class="primary" id="run">▶ Jalankan</button><button class="secondary" id="undo">↶ Hapus terakhir</button><button class="secondary" id="clear">Mulai ulang</button></div>${lesson.world>=4?`<div class="special"><button class="secondary" id="repeat2">↻ Bungkus ulang 2×</button><button class="secondary" id="repeat3">↻ Bungkus ulang 3×</button>${lesson.world>=6?'<button class="secondary" id="saveFn">🪄 Simpan jadi Jurus</button><button class="secondary" id="callFn">🚀 Pakai Jurus</button>':''}</div><p class="hint">Ulang membungkus semua kartu yang sedang tersusun.${lesson.world>=6?' Simpan Jurus memindahkan kartu ke kotak jurus.':''}</p><div id="functionInfo" class="hint"></div>`:''}<button class="secondary" id="hint">💡 Bantu aku berpikir</button></section></div><details class="guide"><summary>☀️ Panduan pendamping · pertemuan ${id+1} · sekitar 20–25 menit</summary><p><b>1. Main tanpa layar (5 menit).</b> ${w.off}</p><p><b>2. Jelajah bersama (10–15 menit).</b> ${w.intro} ${instruction()} Minta anak menunjuk rute dan menebak hasil sebelum menjalankan. Beri kesempatan mencoba ulang.</p><p><b>3. Cerita kembali (5 menit).</b> ${w.ask} Setelah berhasil, coba rencana lain atau minta anak mengajari Anda.</p><p><b>Tanda sudah paham:</b> anak bisa menjelaskan ${w.skill.toLowerCase()} dengan kata-katanya sendiri. Jika belum, ulangi pertemuan ini. Berhenti atau istirahat saat anak mulai lelah.</p></details>`;
$('#back').onclick=map;$('#listen').onclick=()=>{sound=true;updateSound();if(!('speechSynthesis'in window))status('Browser ini belum mendukung pembacaan suara. Pendamping bisa membacakan petunjuk.');else say(instruction());};app.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(running)return;if(program.length>=24)return status('Rencanamu sudah panjang. Hapus beberapa kartu atau pakai pengulangan.');program.push({type:b.dataset.add});drawProgram();});$('#run').onclick=run;$('#undo').onclick=()=>{if(!running){program.pop();drawProgram();}};$('#clear').onclick=()=>{stop();program=[];pos=[...lesson.start];collected.clear();drawBoard();drawProgram();status('Ayo susun rencana baru. Kamu bisa!');};$('#hint').onclick=()=>status(lesson.require==='repeat'?'Cari langkah yang sama. Susun bagian kecilnya, lalu ketuk Ulang 2× atau 3×.':lesson.require==='function'?'Susun panah dan cek bintang. Simpan jadi Jurus, lalu ketuk Pakai Jurus.':lesson.stars.length?'Bintang tidak diambil otomatis. Tambahkan kartu “Jika ⭐, ambil” setelah panah menuju bintang.':`Mulai dengan menunjuk jalan dari Bimo. Langkah pertama menuju ${names[lesson.path[0]].toLowerCase()}.`);if($('#repeat2')){[2,3].forEach(n=>$('#repeat'+n).onclick=()=>{if(running)return;if(!program.length)return status('Isi beberapa panah dulu, baru bungkus dengan Ulang.');if(hasType(program,'repeat'))return status('Untuk sekarang, cukup satu lapis pengulangan.');program=[{type:'repeat',count:n,body:structuredClone(program)}];drawProgram();});}if($('#saveFn')){$('#saveFn').onclick=()=>{if(running)return;if(!program.length)return status('Isi rencana langkah dulu untuk membuat Jurus.');if(hasType(program,'function'))return status('Buat jurus dari panah atau pengulangan, tanpa memanggil dirinya sendiri.');jurus=structuredClone(program);program=[];$('#functionInfo').textContent='Jurus Bimo = '+jurus.map(label).join(' · ');drawProgram();};$('#callFn').onclick=()=>{if(running)return;if(!jurus.length)return status('Simpan langkah menjadi Jurus dulu.');if(program.length>=24)return status('Hapus kartu dulu agar rencana tidak terlalu panjang.');program.push({type:'function',body:structuredClone(jurus)});drawProgram();};}drawBoard();drawProgram();window.scrollTo(0,0);}
function label(c){return c.type==='repeat'?`↻ ${c.count}× [ ${c.body.map(label).join(' ')} ]`:c.type==='function'?`🚀 Jurus [ ${c.body.map(label).join(' ')} ]`:symbols[c.type]+(c.type==='C'?' ?':'');}
function hasType(p,t){return p.some(c=>c.type===t||(c.body&&hasType(c.body,t)));}
function drawProgram(active=-1){$('#program').innerHTML=program.length?program.map((c,i)=>`<button class="token ${c.body?'group':''} ${i===active?'playing':''}" data-remove="${i}" ${running?'disabled':''} aria-label="Hapus kartu ${i+1}: ${label(c)}">${label(c)} <small>×</small></button>`).join(''):'<span class="empty">Rencanamu dimulai di sini<br>↑ Ketuk kartu panah di atas</span>';app.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{program.splice(+b.dataset.remove,1);drawProgram();});$('#run').disabled=running||!program.length;$('#undo').disabled=running||!program.length;app.querySelectorAll('[data-add], .special button').forEach(b=>b.disabled=running);}
function drawBoard(){const cells=[];for(let y=0;y<5;y++)for(let x=0;x<5;x++){const p=[x,y],on=lesson.route.some(q=>eq(p,q)),star=lesson.stars.some(q=>eq(p,q))&&!collected.has(key(p)),here=eq(pos,p);cells.push(`<div class="cell ${on?'path':''} ${here?'here':''}" aria-label="Kolom ${x+1}, baris ${y+1}: ${here?'Bimo':star?'bintang':eq(p,lesson.goal)?'bendera':on?'jalan':'rumput'}">${here?'<span class="bimo">🤖</span>':star?'⭐':eq(p,lesson.goal)?'🚩':on?'':(x+y)%3===0?'🌿':''}</div>`);}$('#board').innerHTML=cells.join('');}
function flatten(p,owner=null){return p.flatMap((c,i)=>{const index=owner===null?i:owner;return c.type==='repeat'?Array.from({length:c.count},()=>flatten(c.body,index)).flat():c.type==='function'?flatten(c.body,index):[{type:c.type,index}];});}
async function run(){if(running||!program.length)return;running=true;const token=++runId;pos=[...lesson.start];collected.clear();drawBoard();drawProgram();const steps=flatten(program);let error='',failedIndex=-1;if(steps.length>150){running=false;drawProgram();return status('Langkahnya terlalu banyak. Mari sederhanakan rencananya.');}for(const c of steps){if(token!==runId)return;drawProgram(c.index);await new Promise(r=>setTimeout(r,580));if(token!==runId)return;if(c.type==='C'){if(lesson.stars.some(s=>eq(s,pos))&&!collected.has(key(pos))){collected.add(key(pos));status('Ada bintang! Bimo mengambilnya. ⭐');}else status('Tidak ada bintang di sini. Bimo lanjut saja.');}else{const d=delta[c.type],p=[pos[0]+d[0],pos[1]+d[1]];if(!lesson.route.some(q=>eq(p,q))){failedIndex=c.index;error='Ups, itu di luar jalan. Cek kartu yang menyala, lalu ubah rencanamu. Kamu boleh coba lagi!';break;}pos=p;}drawBoard();}if(token!==runId)return;running=false;drawProgram(failedIndex);if(error)return status(error);if(!eq(pos,lesson.goal))return status('Bimo belum sampai bendera. Tambahkan atau ubah langkah, lalu coba lagi.');if(collected.size<lesson.stars.length)return status('Sudah sampai! Masih ada bintang tertinggal. Tambahkan “Jika ⭐, ambil” di tempat bintang.');if(lesson.require&&!hasType(program,lesson.require))return status(lesson.require==='repeat'?'Jalanmu benar! Sekarang coba memakai kotak Ulang untuk misi ini.':'Jalanmu benar! Sekarang simpan langkah jadi Jurus dan pakai jurusmu.');if(!done.includes(lesson.id))done.push(lesson.id);try{localStorage.setItem('kode-kecil-v1',JSON.stringify(done));}catch{storageOK=false;}status('Hore! Rencanamu berhasil. Kamu hebat karena terus mencoba!');const id=lesson.id;showDialog(`<div class="celebrate"><div class="big">${id===39?'🏆':'🌟'}</div><div class="eyebrow">PERTEMUAN ${id+1} SELESAI</div><h2>${id===39?'Penjelajah kode kecil!':'Aku bisa, Bimo!'}</h2><p>${worlds[lesson.world].ask}</p><p>Sudah cukup bermain? Istirahat dulu juga boleh.<br>${storageOK?'Progresmu sudah disimpan di browser ini.':'Progres hanya tersimpan selama sesi ini.'}</p><div class="finish-actions"><button class="secondary" id="winMap">Kembali ke peta</button>${id<39?'<button class="primary" id="next">Misi berikutnya →</button>':''}</div></div>`);$('#winMap').onclick=()=>{dialog.close();map();};if($('#next'))$('#next').onclick=()=>{dialog.close();openLesson(id+1);};}
function showDialog(html){dialog.innerHTML='<button class="close" aria-label="Tutup">×</button>'+html;dialog.querySelector('.close').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();}
function parents(){showDialog(`<div class="eyebrow">BELAJAR SAMBIL BERMAIN</div><h2>40 pertemuan, banyak “aha!”</h2><p>Rancangan aktivitas untuk anak usia 6 tahun. Mulai bersama pendamping, tanpa harus bisa membaca lancar. Tombol 🔊 membacakan petunjuk jika browser menyediakan suara bahasa Indonesia.</p><p><b>Ritme yang fleksibel:</b> sekitar 20–25 menit per pertemuan: 5 menit bergerak tanpa layar, 10–15 menit bermain, 5 menit bercerita. Boleh lebih singkat dan boleh mengulang. Semua misi terbuka agar pendamping bisa menyesuaikan.</p><p><b>Tujuan:</b> anak dapat menyusun instruksi, menemukan kesalahan, mengenali pola, memakai pengulangan, kondisi sederhana, dan fungsi. “Jago” di sini berarti mampu menjelaskan rencananya sendiri, bukan mahir bahasa pemrograman.</p><div class="curriculum">${worlds.map((w,i)=>`<details><summary>${w.icon} ${i*5+1}–${i*5+5} · ${w.name} — ${w.skill}</summary><p>${w.off}</p><ol start="${i*5+1}">${lessons.slice(i*5,i*5+5).map(l=>`<li><b>${l.title}.</b> ${l.world===2?'Temukan panah yang salah dan perbaiki':l.require==='repeat'?'Ringkas pola dengan blok ulang':l.require==='function'?'Buat dan panggil jurus':l.stars.length?'Gunakan kondisi untuk mengambil bintang':'Rencanakan urutan panah'} pada rute ${l.path.length} langkah${l.stars.length?', dengan '+l.stars.length+' bintang':''}.</li>`).join('')}</ol><p>Refleksi: ${w.ask}</p></details>`).join('')}</div><p><b>Progres:</b> ${done.length}/40 misi. Tersimpan hanya di browser dan perangkat ini; tidak tersinkron antarperangkat. Tidak meminta nama atau data anak.</p><button class="secondary" id="export">↓ Unduh progres</button> <button class="secondary" id="print">Cetak panduan 40 pertemuan</button>`);$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({app:'Kode Kecil',completed:done.map(id=>({pertemuan:id+1,judul:lessons[id].title})),total:40},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='progres-kode-kecil.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#print').onclick=()=>{dialog.querySelectorAll('details').forEach(d=>d.open=true);window.print();};}
function updateSound(){$('#soundBtn').textContent=sound?'♫':'♪';$('#soundBtn').setAttribute('aria-label',sound?'Matikan suara':'Aktifkan suara');$('#soundBtn').setAttribute('aria-pressed',String(sound));}
$('#mapBtn').onclick=map;$('.brand').onclick=e=>{e.preventDefault();map();};$('#parentsBtn').onclick=parents;$('#soundBtn').onclick=()=>{sound=!sound;updateSound();if(sound)say('Halo! Aku Bimo. Ayo bermain bersama.');else if('speechSynthesis'in window)speechSynthesis.cancel();};map();
